function joinGroupAndVisit() {
    // 获取所有 "加入小组按钮"
    const joinButtons = document.querySelectorAll('div[aria-label="加入小组按钮"]');

    if (joinButtons.length === 0) {
        console.log('没有找到任何 "加入小组按钮"');
        return;
    }

    // 随机选择一个按钮点击
    const randomIndex = Math.floor(Math.random() * joinButtons.length);
    const selectedButton = joinButtons[randomIndex];
    selectedButton.click();
    console.log(`已点击第 ${randomIndex + 1} 个加入小组按钮`);

    // 等待 2 秒后点击 "访问小组" 按钮
    setTimeout(() => {
        const visitButton = document.querySelector('div[aria-label="“访问小组”按钮"]');
        if (visitButton) {
            visitButton.click();
            console.log('已点击 “访问小组” 按钮');
        } else {
            console.log('未找到 “访问小组” 按钮');
        }
    }, 2000);
}

