function simulateClick(el) {
  if (!el) return false;
  try {
    const event = new MouseEvent('click', {
      bubbles: true,
      cancelable: true,
      view: window
    });
    el.dispatchEvent(event);
    console.log("✅ 成功点击目标元素");
    return true;
  } catch (e) {
    console.warn("❌ 点击失败", e);
    return false;
  }
}

function clickExactTarget() {
  const el = document.querySelector('#screen-root > div > div:nth-child(3) > div:nth-child(6) > div:nth-child(2) > div > div > div');
  if (el) {
    return simulateClick(el);
  } else {
    console.log("⏳ 正在等待元素加载...");
    return false;
  }
}

// 每秒尝试一次，直到点击成功
