const targetSelector = "#screen-root > div > div:nth-child(2) > div:nth-child(2) > div:nth-child(3) > div > div > span";

// 封装点击函数，带重试机制
function forceClick(selector, maxRetries = 10, delay = 500) {
  let attempts = 0;

  function tryClick() {
    const el = document.querySelector(selector);
    if (el) {
      el.click();
      console.log(`✅ 成功点击元素：${selector}`);
    } else if (attempts < maxRetries) {
      attempts++;
      console.log(`⏳ 第 ${attempts} 次尝试未找到元素，${delay}ms 后重试...`);
      setTimeout(tryClick, delay);
    } else {
      console.error(`❌ 超过最大重试次数，未找到元素：${selector}`);
    }
  }

  tryClick();
}

// 开始点击流程
forceClick(targetSelector);

