(() => {
  const probe = () => {
    const body = document.body ? document.body.innerText : "";
    const hasComposer = !!document.querySelector('[aria-label*="创建帖子"], [aria-label*="发布"], [aria-label*="分享你的想法"]');
    const hasHome = !!document.querySelector('a[href*="/me/"], a[href*="/profile.php"], [aria-label*="个人主页"], [aria-label*="你的主页"]');
    return hasComposer || hasHome || /个人主页|你的主页|创建帖子|分享你的想法/.test(body);
  };
  if (probe()) return "logged-in";
  return new Promise((resolve) => {
    const t0 = Date.now();
    const iv = setInterval(() => {
      if (probe()) { clearInterval(iv); resolve("logged-in"); }
      else if (Date.now() - t0 > 15000) { clearInterval(iv); resolve("not-logged-in"); }
    }, 1500);
  });
})()
